        private static readonly byte[] Cells = Convert.FromBase64String(CellsBase64);

        public const float CoverageResidentialPercent = 27.02f;
        public const float CoverageCommercialPercent = 4.25f;
        public const float CoverageParkPercent = 6.03f;
        public const float CoverageParkingPercent = 2.6f;
        public const float CoverageWaterPercent = 0.74f;
        public const float CoverageSandPercent = 1.42f;
        public const float CoverageScrubPercent = 0.38f;
        public const float CoverageGolfPercent = 1.63f;

        public static Kind Sample(float x, float z)
        {
            if (Cells == null || Cells.Length != Size * Size)
                return Kind.None;
            var xi = (int)Math.Floor((x - OriginMetres) / CellMetres);
            var zi = (int)Math.Floor((z - OriginMetres) / CellMetres);
            if ((uint)xi >= Size || (uint)zi >= Size)
                return Kind.None;
            return (Kind)Cells[zi * Size + xi];
        }

        public static bool InOperationalCore(float x, float z) =>
            Math.Abs(x) < CoreHalfXMetres && Math.Abs(z) < CoreHalfZMetres;
    }
